def _embedded_3d_photo(asset_name):
    """Return a fresh stream for an embedded 3D JPEG asset."""
    assets = {
        "coursework": (_COURSEWORK_3D_JPEG_B64, "coursework_3d.jpg"),
        "student_events": (_STUDENT_EVENTS_3D_JPEG_B64, "student_events_3d.jpg"),
    }
    if asset_name not in assets:
        raise ValueError("Unknown embedded artwork asset")
    encoded, filename = assets[asset_name]
    stream = io.BytesIO(base64.b64decode(encoded))
    stream.name = filename
    return stream

def _portal_dashboard_photo():
    stream = io.BytesIO(base64.b64decode(_PORTAL_DASHBOARD_JPEG_B64))
    stream.name = "university_portal.jpg"
    return stream


def record_portal_usage(user_id):
    """Record a portal opening for weekly aggregate statistics; no message content is stored."""
    try:
        local_now = _riyadh_now()
        db.execute(
            "INSERT INTO portal_usage_events(user_id,event_at,week_start) VALUES(?,?,?)",
            (int(user_id), local_now.isoformat(), _week_start(local_now))
        )
        db.commit()
    except Exception:
        log.exception("تعذر تسجيل استخدام بوابتي الجامعية")


def _portal_week_stats(week_start):
    from datetime import date, timedelta
    start = date.fromisoformat(week_start)
    end = start + timedelta(days=7)
    total_visits = db.execute(
        "SELECT COUNT(*) FROM portal_usage_events WHERE week_start=?", (week_start,)
    ).fetchone()[0]
    unique_users = db.execute(
        "SELECT COUNT(DISTINCT user_id) FROM portal_usage_events WHERE week_start=?", (week_start,)
    ).fetchone()[0]
    daily = []
    for offset in range(7):
        day = (start + timedelta(days=offset)).isoformat()
        count = db.execute(
            "SELECT COUNT(DISTINCT user_id) FROM portal_usage_events WHERE event_at>=? AND event_at<?",
            (day + "T00:00:00", (start + timedelta(days=offset+1)).isoformat() + "T00:00:00")
        ).fetchone()[0]
        daily.append((day, count))
    return {"start": start.isoformat(), "end": (end - timedelta(days=1)).isoformat(),
            "visits": total_visits, "unique_users": unique_users, "daily": daily}


def _portal_stats_chart(stats):
    """Create a PNG bar chart when matplotlib is installed; returns None otherwise."""
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        from datetime import date
        labels = [date.fromisoformat(day).strftime("%a %d") for day, _ in stats["daily"]]
        values = [count for _, count in stats["daily"]]
        fig, ax = plt.subplots(figsize=(9, 4.8), dpi=150)
        bars = ax.bar(labels, values)
        ax.set_title("University Portal — Unique Students per Day")
        ax.set_ylabel("Unique students")
        ax.set_xlabel("Day")
        ax.grid(axis="y", alpha=0.25)
        ax.bar_label(bars, padding=3, fmt="%d")
        ax.set_ylim(0, max(values + [1]) * 1.25)
        fig.tight_layout()
        stream = io.BytesIO()
        fig.savefig(stream, format="png", bbox_inches="tight")
        plt.close(fig)
        stream.seek(0)
        stream.name = "university_portal_weekly_stats.png"
        return stream
    except Exception as exc:
        log.warning("تعذر إنشاء الرسم البياني لإحصائية البوابة: %s", exc)
        return None


async def portal_stats_cmd(update, context):
    """Owner-only on-demand weekly usage report for the university portal."""
    if not is_owner(update.effective_user.id if update.effective_user else 0):
        await update.effective_message.reply_text("هذه الإحصائية متاحة للمالك الأساسي فقط.")
        return
    week = _week_start()
    stats = _portal_week_stats(week)
    report = (f"📊 إحصائية بوابتي الجامعية لهذا الأسبوع\n"
              f"📅 الفترة: {stats['start']} إلى {stats['end']}\n"
              f"👥 عدد الطلبة/الطالبات المستخدمين (دون تكرار): {stats['unique_users']:,}\n"
              f"🔁 إجمالي مرات فتح اللوحة: {stats['visits']:,}\n"
              "ℹ️ يُحتسب المستخدم عند فتح لوحة بوابتي الجامعية، وتبدأ البيانات من تاريخ تفعيل الرصد.")
    chart = _portal_stats_chart(stats)
    if chart:
        await update.effective_message.reply_photo(photo=chart, caption=report)
    else:
        await update.effective_message.reply_text(report + "\n(تعذر إنشاء الرسم البياني في بيئة التشغيل؛ الأرقام متاحة أعلاه.)")


async def portal_weekly_stats_worker(app):
    """Send owner a weekly numeric report and chart every Sunday at 20:10 Riyadh time."""
    from datetime import timedelta
    while True:
        try:
            if not OWNER_ID:
                await asyncio.sleep(3600)
                continue
            local_now = _riyadh_now()
            days_until_sunday = (6 - local_now.weekday()) % 7
            target = local_now.replace(hour=20, minute=10, second=0, microsecond=0) + timedelta(days=days_until_sunday)
            if target <= local_now:
                target += timedelta(days=7)
            await asyncio.sleep(max(30, (target - local_now).total_seconds()))
            local_now = _riyadh_now()
            current_week_start = _week_start(local_now)
            previous_week_start = (local_now.date() - timedelta(days=local_now.weekday()+7)).isoformat()
            sent = db.execute("SELECT 1 FROM portal_weekly_reports WHERE week_start=?", (previous_week_start,)).fetchone()
            if sent:
                continue
            stats = _portal_week_stats(previous_week_start)
            report = (f"📊 التقرير الأسبوعي لاستخدام بوابتي الجامعية\n"
                      f"📅 الفترة: {stats['start']} إلى {stats['end']}\n"
                      f"👥 الطلبة والطالبات المستخدمون (دون تكرار): {stats['unique_users']:,}\n"
                      f"🔁 إجمالي مرات فتح اللوحة: {stats['visits']:,}\n"
                      "📈 الرسم يوضح عدد المستخدمين الفريدين في كل يوم.\n"
                      "ℹ️ يبدأ الرصد من تاريخ إضافة هذه الميزة، ولا يشمل الاستخدام السابق.")
            chart = _portal_stats_chart(stats)
            if chart:
                await app.bot.send_photo(chat_id=OWNER_ID, photo=chart, caption=report)
            else:
                await app.bot.send_message(chat_id=OWNER_ID, text=report + "\n(الرسم غير متاح في بيئة التشغيل؛ الأرقام محفوظة.)")
            db.execute("INSERT OR IGNORE INTO portal_weekly_reports(week_start,sent_at) VALUES(?,?)", (previous_week_start, now()))
            db.commit()
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("خطأ في تقرير استخدام بوابتي الجامعية الأسبوعي")
            await asyncio.sleep(60)


