        await q.edit_message_text(text, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("⬅️ سجل الرسائل", callback_data="archive")],[InlineKeyboardButton("⬅️ الرئيسية", callback_data="home")]]))
